def find_all_primitive_roots(p):
    """Find all primitive roots modulo p."""
    def is_primitive_root(g, p):
        phi = p - 1
        factors = set()
        n = phi
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)

        for q in factors:
            if pow(g, phi // q, p) == 1:
                return False
        return True

