def gf27_mul(a, b):
    a0, a1, a2 = a
    b0, b1, b2 = b
    c0 = (a0*b0 + 2*a1*b2 + 2*a2*b1) % 3
    c1 = (a0*b1 + a1*b0 + 2*a2*b2) % 3
    c2 = (a0*b2 + a1*b1 + a2*b0) % 3
    return (c0, c1, c2)

def gf27_pow(a, exp):
    result = (1, 0, 0)
    base = a
    while exp > 0:
        if exp % 2 == 1:
            result = gf27_mul(result, base)
        base = gf27_mul(base, base)
        exp //= 2
    return result

