# Bron-Kerbosch with pivoting to find maximum clique
def bron_kerbosch(R, P, X, best):
    if not P and not X:
        if len(R) > len(best[0]):
            best[0] = list(R)
        return
    if len(R) + len(P) <= len(best[0]):
        return

    # Choose pivot
    pivot = max(P | X, key=lambda v: len(P & adj[v]))

    for v in list(P - adj[pivot]):
        bron_kerbosch(R | {v}, P & adj[v], X & adj[v], best)
        P = P - {v}
        X = X | {v}

