from collections import deque

def find_girth(edges, n):
    """Find the girth (shortest cycle length) of a graph."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')

    for start in range(n):
        # BFS to find shortest cycle through start
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle if min_cycle != float('inf') else -1

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for u in adj[v]:
                if color[u] == c:
                    valid = False
                    break
            if valid:
                color[v] = c
                if backtrack(v + 1):
                    return True
                color[v] = -1
        return False

    return backtrack(0)

