    return True

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(vertex):
        if vertex == n:
            return True
        for color in range(k):
            valid = True
            for neighbor in adj[vertex]:
                if colors[neighbor] == color:
                    valid = False
                    break
            if valid:
                colors[vertex] = color
                if backtrack(vertex + 1):
                    return True
                colors[vertex] = -1
        return False

    return backtrack(0)

