def is_k_colorable(G, k):
    """Check if graph is k-colorable using backtracking"""
    n = G.number_of_nodes()
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in G.neighbors(v):
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

