        neighbors = list(adj[i])
        for j_idx in range(len(neighbors)):
            for k_idx in range(j_idx+1, len(neighbors)):
                j, k = neighbors[j_idx], neighbors[k_idx]
                # Check if j and k have a common neighbor other than i
                common = adj[j] & adj[k] - {i}
                if common:
                    return False, 4

    # Check for 5-cycles using BFS
    from collections import deque
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 6:
                        return False, cycle_len

    return True, float('inf')

def check_4colorable(edges, n):
    """Check if the graph is 4-colorable using backtracking"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(4):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

