def solve_qg3_backtrack(n):
    # Initialize grid with -1 (unassigned)
    grid = [[-1]*n for _ in range(n)]

    # Set diagonal
    for i in range(n):
        grid[i][i] = i

    # Track used values in each row and column
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    for i in range(n):
        row_used[i].add(i)
        col_used[i].add(i)

    # Get list of cells to fill (excluding diagonal)
    cells = [(i, j) for i in range(n) for j in range(n) if i != j]

    def is_valid(i, j, val):
        if val in row_used[i] or val in col_used[j]:
            return False
        return True

    def check_qg3_partial():
        # Check QG3 constraint for all fully determined triples
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if a >= 0 and b >= 0 and grid[a][b] >= 0:
                    if grid[a][b] != i:
                        return False
        return True

    def solve(idx):
        if idx == len(cells):
            return True

        i, j = cells[idx]

        for val in range(n):
            if is_valid(i, j, val):
                grid[i][j] = val
                row_used[i].add(val)
                col_used[j].add(val)

                if check_qg3_partial():
                    if solve(idx + 1):
