        for v in range(n):
            lits = [var(i, j, v) for i in range(n)]
            solver.add_clause(lits)
            for k in range(len(lits)):
                for l in range(k+1, len(lits)):
                    solver.add_clause([-lits[k], -lits[l]])

    # Idempotent diagonal
    for i in range(n):
        solver.add_clause([var(i, i, i)])

    # QG3 constraint
    for i in range(n):
        for j in range(n):
            for a in range(n):
                for b in range(n):
                    solver.add_clause([-var(i, j, a), -var(j, i, b), var(a, b, i)])

    print(f"Solving for n={n} with Cadical...")

    if solver.solve():
        model = solver.get_model()
        grid = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for v in range(n):
                    if var(i, j, v) in model:
                        grid[i][j] = v
                        break
        return grid
    else:
        return None

