from z3 import *
import time

num_golfers = 50
num_groups = 10
group_size = 5
num_weeks = 7

# Use a different approach: encode as SAT with cardinality constraints
# Variable x[w][p][g] = 1 if golfer p is in group g in week w

solver = Solver()
solver.set("timeout", 55000)  # 55 seconds

# Create boolean variables
x = [[[Bool(f'x_{w}_{p}_{g}') for g in range(num_groups)] 
      for p in range(num_golfers)] for w in range(num_weeks)]

# Constraint 1: Each golfer is in exactly one group each week
for w in range(num_weeks):
    for p in range(num_golfers):
        # At least one
        solver.add(Or([x[w][p][g] for g in range(num_groups)]))
        # At most one (pairwise)
        for g1 in range(num_groups):
            for g2 in range(g1+1, num_groups):
                solver.add(Not(And(x[w][p][g1], x[w][p][g2])))

# Constraint 2: Each group has exactly 5 golfers each week
for w in range(num_weeks):
    for g in range(num_groups):
        # Exactly 5 golfers in group g
        solver.add(PbEq([(x[w][p][g], 1) for p in range(num_golfers)], group_size))

# Constraint 3: No pair in same group more than once
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        for w1 in range(num_weeks):
            for w2 in range(w1+1, num_weeks):
                for g in range(num_groups):
                    # Not both in group g in both weeks
                    solver.add(Not(And(x[w1][p1][g], x[w1][p2][g], x[w2][p1][g], x[w2][p2][g])))

print("Constraints added, solving...")
start = time.time()
result = solver.check()
elapsed = time.time() - start
print(f"Result: {result}, time: {elapsed:.2f}s")

if result == sat:
    m = solver.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            for g in range(num_groups):
                if m.evaluate(x[w][p][g]):
                    solution.append(g)
                    break
    print(f"Solution found! Length: {len(solution)}")
    print(f"First 50: {solution[:50]}")
else:
    print("UNSAT or timeout")
    solution = None

